/**
 * Unit tests for {@link SubLine#intersection(SubLine, boolean)}.
 */
public class SubLine_intersection_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_BothInside_IncludeEndPointsTrue() {
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 10));
        SubLine line2 = new SubLine(new Vector2D(0, 10), new Vector2D(10, 0));

        // Intersection at (5, 5)
        Vector2D result = line1.intersection(line2, true);

        assertNotNull("Result should not be null", result);
        assertEquals(5.0, result.getX(), EPSILON);
        assertEquals(5.0, result.getY(), EPSILON);
    }












}

