    private static final double EPSILON = 1e-10;





    @Test
    public void testIntersection_OnEndPoint_IncludeEndPointsTrue() {
        // line1: (0,0) to (10,10)
        // line2: (10,10) to (20,0)
        // Intersection is at (10,10), which is an endpoint
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 10));
        SubLine line2 = new SubLine(new Vector2D(10, 10), new Vector2D(20, 0));

        Vector2D result = line1.intersection(line2, true);

        assertNotNull("Result should not be null when including endpoints", result);
        assertEquals(10.0, result.getX(), EPSILON);
        assertEquals(10.0, result.getY(), EPSILON);
    }








