/**
 * Unit tests for {@link SubLine#intersection(SubLine, boolean)}.
 */
public class SubLine_intersection_TriageGen2Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testIntersection_OnEndPoint_IncludeEndPointsFalse() {
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 10));
        SubLine line2 = new SubLine(new Vector2D(10, 10), new Vector2D(20, 0));

        // Endpoint is NOT considered "INSIDE" (usually BETWEEN), it is BOUNDARY.
        // In Commons Math, checkPoint returns INSIDE for points strictly within the region.
        // If loc is BOUNDARY, (loc == Location.INSIDE) is false.
        Vector2D result = line1.intersection(line2, false);

        assertNull("Result should be null when excluding endpoints and intersection is on boundary", result);
    }






}

