public class SubLine_intersection_TriageGen2Test {

    private static final double EPSILON = 1e-10;













    @Test(expected = ArithmeticException.class)
    public void testIntersection_ParallelLines() {
        // Parallel lines should throw exception during line1.intersection(line2) 
        // or return null depending on implementation, but usually parallel lines 
        // in Commons Math cause division by zero/ArithmeticException.
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 0));
        SubLine line2 = new SubLine(new Vector2D(0, 1), new Vector2D(10, 1));

        line1.intersection(line2, true);
    }
